[CmdletBinding()] param()
$ErrorActionPreference='Stop';$qaRoot=Split-Path -Parent $PSScriptRoot
$config=Get-Content -Raw (Join-Path $qaRoot 'supabase\config.toml');if($config-notmatch'project_id\s*=\s*"inventory_qa"'-or$config-match'https://|supabase\.co|xxownwxxajzrviuvvfiu'){throw'Local QA isolation guard failed.'}
$old=$ErrorActionPreference;$ErrorActionPreference='Continue';$env=@(npx --yes --package=supabase@2.121.0 -- supabase --workdir $qaRoot status -o env 2>$null);$ErrorActionPreference=$old
$anon=((@($env|Where-Object{$_-match'^ANON_KEY='})[0]-split'=',2)[1]).Trim('"');$base='http://127.0.0.1:56321';$auth=@{apikey=$anon;Authorization="Bearer $anon"}
function New-Actor($label){$e="im1b5-$label-$([guid]::NewGuid().ToString('N'))@example.invalid";$p=[guid]::NewGuid().ToString('N')+'!Aa1';$s=Invoke-RestMethod -Method Post -Uri "$base/auth/v1/signup" -Headers $auth -ContentType 'application/json' -Body(@{email=$e;password=$p}|ConvertTo-Json);@{Id=[string]$s.user.id;Token=[string]$s.access_token}}
function Rpc($token,$name,$body){Invoke-RestMethod -Method Post -Uri "$base/rest/v1/rpc/$name" -Headers @{apikey=$anon;Authorization="Bearer $token"} -ContentType 'application/json' -Body($body|ConvertTo-Json -Depth 8)}
function Denied($token,$name,$body,$code,$message){try{Rpc $token $name $body|Out-Null;$false}catch{([int]$_.Exception.Response.StatusCode-eq$code)-and([string]$_.ErrorDetails.Message-match$message)}}
function ErrorSignature($token,$name,$body){try{Rpc $token $name $body|Out-Null;'SUCCESS'}catch{$payload=([string]$_.ErrorDetails.Message|ConvertFrom-Json);"$([int]$_.Exception.Response.StatusCode)|$($payload.code)|$($payload.message)"}}
$teacher=New-Actor teacher;$instructor=New-Actor instructor;$inactive=New-Actor inactive
$school='c5100000-0000-4000-8000-000000000001';$other='c5100000-0000-4000-8000-000000000002';$item='c5200000-0000-4000-8000-000000000001';$batch='c5300000-0000-4000-8000-000000000001'
@"
insert into public.inventory_schools(school_id,display_name) values('$school','Synthetic HTTP Purchase'),('$other','Synthetic Other');
insert into public.inventory_members(school_id,user_id,role,is_active) values('$school','$($teacher.Id)','teacher_admin',true),('$school','$($instructor.Id)','instructor',true),('$school','$($inactive.Id)','teacher_admin',false);
insert into public.inventory_items(item_id,school_id,item_name,base_unit,purchase_unit,base_units_per_purchase_unit) values('$item','$school','Synthetic HTTP Purchase Item','piece','box',10);
"@|docker exec -i supabase_db_inventory_qa psql -X -q -v ON_ERROR_STOP=1 -U postgres -d postgres
$line=@{candidate_id='http-line';item_id=$item;requested_purchase_quantity=10;base_unit='piece';purchase_unit='box';base_units_per_purchase_unit=10;specification_snapshot='synthetic';expected_unit_price=1000;currency='KRW'}
$create=@{p_school_id=$school;p_batch_id=$batch;p_request_uuid='c5900000-0000-4000-8000-000000000001';p_note='Synthetic HTTP batch';p_lines=@($line)}
$c=Rpc $teacher.Token inventory_create_purchase_batch $create
foreach($s in @(@('APPROVED','2'),@('ORDERED','3'),@('AWAITING_RECEIPT','4'))){Rpc $teacher.Token inventory_set_purchase_batch_status @{p_school_id=$school;p_batch_id=$batch;p_target_status=$s[0];p_request_uuid="c5900000-0000-4000-8000-00000000000$($s[1])";p_reason='Synthetic status'}|Out-Null}
$lineId=(@("select line_id from public.inventory_purchase_lines where batch_id='$batch';"|docker exec -i supabase_db_inventory_qa psql -X -qAt -U postgres -d postgres)[0]).Trim()
$receipt=@{p_school_id=$school;p_batch_id=$batch;p_receipt_id='c5400000-0000-4000-8000-000000000001';p_request_uuid='c5900000-0000-4000-8000-000000000010';p_received_at='2026-11-02T00:00:00Z';p_reason='Synthetic HTTP receipt';p_lines=@(@{line_id=$lineId;received_purchase_quantity=4;expires_on='2027-11-02'})}
$r=Rpc $teacher.Token inventory_confirm_receipt $receipt;$replay=Rpc $teacher.Token inventory_confirm_receipt $receipt
$conf=$receipt.Clone();$conf.p_lines=@(@{line_id=$lineId;received_purchase_quantity=3;expires_on='2027-11-02'});$conflict=Denied $teacher.Token inventory_confirm_receipt $conf 409 'IDEMPOTENCY_CONFLICT'
$dup=$receipt.Clone();$dup.p_request_uuid='c5900000-0000-4000-8000-000000000011';$duplicate=Denied $teacher.Token inventory_confirm_receipt $dup 409 'DUPLICATE_RECEIPT'
$instr=$receipt.Clone();$instr.p_receipt_id='c5400000-0000-4000-8000-000000000002';$instr.p_request_uuid='c5900000-0000-4000-8000-000000000012';$instructorDenied=Denied $instructor.Token inventory_confirm_receipt $instr 403 'PERMISSION_DENIED'
$inactiveBody=$instr.Clone();$inactiveBody.p_request_uuid='c5900000-0000-4000-8000-000000000013';$inactiveDenied=Denied $inactive.Token inventory_confirm_receipt $inactiveBody 403 'PERMISSION_DENIED'
$cross=$receipt.Clone();$cross.p_school_id=$other;$cross.p_receipt_id='c5400000-0000-4000-8000-000000000003';$cross.p_request_uuid='c5900000-0000-4000-8000-000000000014';$crossDenied=Denied $teacher.Token inventory_confirm_receipt $cross 403 'PERMISSION_DENIED'
$anonDenied=Denied $anon inventory_confirm_receipt $instr 401 'UNAUTHENTICATED|permission denied'
$linkedMovement=[string]$r.receipt_lines[0].movement_id;$randomMovement='ffffffff-ffff-4fff-8fff-ffffffffffff'
$instructorLinked=ErrorSignature $instructor.Token inventory_reverse_movement @{p_school_id=$school;p_original_movement_id=$linkedMovement;p_request_uuid='c5900000-0000-4000-8000-000000000020';p_reason='probe'};$instructorRandom=ErrorSignature $instructor.Token inventory_reverse_movement @{p_school_id=$school;p_original_movement_id=$randomMovement;p_request_uuid='c5900000-0000-4000-8000-000000000021';p_reason='probe'}
$inactiveLinked=ErrorSignature $inactive.Token inventory_reverse_movement @{p_school_id=$school;p_original_movement_id=$linkedMovement;p_request_uuid='c5900000-0000-4000-8000-000000000022';p_reason='probe'};$inactiveRandom=ErrorSignature $inactive.Token inventory_reverse_movement @{p_school_id=$school;p_original_movement_id=$randomMovement;p_request_uuid='c5900000-0000-4000-8000-000000000023';p_reason='probe'}
$crossLinked=ErrorSignature $teacher.Token inventory_reverse_movement @{p_school_id=$other;p_original_movement_id=$linkedMovement;p_request_uuid='c5900000-0000-4000-8000-000000000024';p_reason='probe'};$crossRandom=ErrorSignature $teacher.Token inventory_reverse_movement @{p_school_id=$other;p_original_movement_id=$randomMovement;p_request_uuid='c5900000-0000-4000-8000-000000000025';p_reason='probe'}
$nonDisclosing=$instructorLinked-eq'403|PT403|PERMISSION_DENIED'-and$instructorRandom-eq$instructorLinked-and$inactiveLinked-eq'403|PT403|PERMISSION_DENIED'-and$inactiveRandom-eq$inactiveLinked-and$crossLinked-eq'403|PT403|PERMISSION_DENIED'-and$crossRandom-eq$crossLinked
try{Invoke-RestMethod -Method Patch -Uri "$base/rest/v1/inventory_purchase_lines?line_id=eq.$lineId" -Headers @{apikey=$anon;Authorization="Bearer $($teacher.Token)";Prefer='return=representation'} -ContentType 'application/json' -Body'{"received_base_quantity":999}'|Out-Null;$actual=[string](@("select received_base_quantity from public.inventory_purchase_lines where batch_id='$batch';"|docker exec -i supabase_db_inventory_qa psql -X -qAt -U postgres -d postgres)|Select-Object -Last 1);$direct=$actual.Trim()-eq'40'}catch{$direct=$true}
$pass=$c.status-eq'DRAFT'-and$r.status-eq'PARTIALLY_RECEIVED'-and$replay.replayed-and$conflict-and$duplicate-and$instructorDenied-and$inactiveDenied-and$crossDenied-and$anonDenied-and$direct-and$nonDisclosing
if(-not $pass){throw "IM-1B-5 HTTP E2E failed conflict=$conflict duplicate=$duplicate instructor=$instructorDenied inactive=$inactiveDenied cross=$crossDenied anon=$anonDenied direct=$direct batchStatus=$($c.status) receiptStatus=$($r.status) replay=$($replay.replayed) nonDisclosing=$nonDisclosing instructorLinked=[$instructorLinked] instructorRandom=[$instructorRandom] inactiveLinked=[$inactiveLinked] inactiveRandom=[$inactiveRandom] crossLinked=[$crossLinked] crossRandom=[$crossRandom]"}
[pscustomobject]@{suite='IM-1B-5-http';status='PASS';batchCreated=$true;partialReceipt=$true;replay=$true;conflict=$conflict;duplicateReceipt=$duplicate;instructorDenied=$instructorDenied;inactiveDenied=$inactiveDenied;crossTenantDenied=$crossDenied;anonDenied=$anonDenied;directDmlDenied=$direct;reversalProbeNonDisclosing=$nonDisclosing}
$anon=$null;$teacher.Token=$null;$instructor.Token=$null;$inactive.Token=$null
